def section68_applies(facts):
    year = facts.get('query_year')
    if not isinstance(year, int) or isinstance(year, bool):
        return {'value': None, 'used_units': ['u68_f_pred'], 'open_dependencies': ['query_year is required from the legal query']}
    return {'value': not (2018 <= year <= 2025), 'used_units': ['u68_f_pred'], 'open_dependencies': []}

def section68_applicable_amount(facts):
    status = facts.get('filing_status')
    if not isinstance(status, str):
        return {'value': None, 'used_units': ['u68_b_qty'], 'open_dependencies': ['filing_status is required']}
    status = status.strip().lower().replace('-', '_').replace(' ', '_')
    if status in ('joint', 'joint_return', 'married_filing_jointly', 'surviving_spouse'):
        value = 300000
    elif status in ('head_of_household', 'hoh'):
        value = 275000
    elif status in ('single', 'unmarried', 'not_married'):
        value = 250000
    elif status in ('married_filing_separately', 'married_separate', 'mfs', 'separate_return'):
        value = 150000
    else:
        return {'value': None, 'used_units': ['u68_b_qty'], 'open_dependencies': ['filing_status must identify joint return, surviving spouse, head of household, an unmarried individual, or married filing separately']}
    return {'value': value, 'used_units': ['u68_b_qty'], 'open_dependencies': []}

def qualifying_child(facts):
    stated = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

    unknown = []
    relationship = facts.get('relationship_to_taxpayer')
    relationship_ok = None
    if isinstance(relationship, str):
        r = relationship.strip().lower().replace('-', '_').replace(' ', '_')
        allowed = ('child', 'descendant_of_child', 'grandchild', 'brother', 'sister', 'stepbrother', 'stepsister', 'descendant_of_brother', 'descendant_of_sister', 'niece', 'nephew')
        if r in allowed:
            relationship_ok = True
        else:
            unknown.append('relationship_to_taxpayer does not identify a recognized qualifying relationship')
    else:
        unknown.append('relationship_to_taxpayer is required')

    abode = facts.get('same_principal_abode_more_than_half_taxable_year')
    if not isinstance(abode, bool):
        abode = None
        unknown.append('same_principal_abode_more_than_half_taxable_year is required')

    child_age = facts.get('individual_age_at_end_of_taxable_year')
    taxpayer_age = facts.get('taxpayer_age_at_end_of_taxable_year')
    age_ok = None
    if isinstance(child_age, int) and not isinstance(child_age, bool) and isinstance(taxpayer_age, int) and not isinstance(taxpayer_age, bool):
        age_ok = child_age < taxpayer_age and child_age < 25
    else:
        unknown.append('individual_age_at_end_of_taxable_year and taxpayer_age_at_end_of_taxable_year are required')

    filed_joint = facts.get('individual_filed_joint_return_with_spouse')
    refund_only = facts.get('joint_return_filed_only_for_refund')
    joint_ok = None
    if isinstance(filed_joint, bool):
        if not filed_joint:
            joint_ok = True
        elif isinstance(refund_only, bool):
            joint_ok = refund_only
        else:
            unknown.append('joint_return_filed_only_for_refund is required when a joint return was filed')
    else:
        unknown.append('individual_filed_joint_return_with_spouse is required')

    conditions = (relationship_ok, abode, age_ok, joint_ok)
    if False in conditions:
        return {'value': False, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}
    if None in conditions:
        return {'value': None, 'used_units': ['u152_c1_pred'], 'open_dependencies': unknown}
    return {'value': True, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

def qualifying_relative(facts):
    unknown = []
    relationship = facts.get('relationship_to_taxpayer')
    direct_ok = None
    is_excluded_spouse = False
    if isinstance(relationship, str):
        r = relationship.strip().lower().replace('-', '_').replace(' ', '_')
        direct = ('child', 'descendant_of_child', 'grandchild', 'brother', 'sister', 'stepbrother', 'stepsister', 'father', 'mother', 'ancestor_of_father', 'ancestor_of_mother', 'grandfather', 'grandmother', 'stepfather', 'stepmother', 'son_of_brother', 'daughter_of_brother', 'son_of_sister', 'daughter_of_sister', 'nephew', 'niece', 'brother_of_father', 'sister_of_father', 'brother_of_mother', 'sister_of_mother', 'uncle', 'aunt', 'son_in_law', 'daughter_in_law', 'father_in_law', 'mother_in_law', 'brother_in_law', 'sister_in_law')
        if r in direct:
            direct_ok = True
        elif r in ('spouse', 'husband', 'wife'):
            direct_ok = False
            is_excluded_spouse = True

    household_ok = None
    if not is_excluded_spouse:
        same_abode = facts.get('same_principal_abode_for_entire_taxable_year')
        household_member = facts.get('member_of_taxpayer_household')
        spouse_during_year = facts.get('was_taxpayer_spouse_at_any_time_during_taxable_year')
        household_conditions = (same_abode, household_member, None if not isinstance(spouse_during_year, bool) else not spouse_during_year)
        if False in household_conditions:
            household_ok = False
        elif all(isinstance(v, bool) for v in household_conditions):
            household_ok = True
    else:
        household_ok = False

    if direct_ok is True or household_ok is True:
        relationship_ok = True
    elif direct_ok is False and household_ok is False:
        relationship_ok = False
    else:
        relationship_ok = None
        unknown.append('a recognized qualifying relationship or all household-member facts are required')

    income = facts.get('individual_income_for_calendar_year')
    no_income = None
    if isinstance(income, (int, float)) and not isinstance(income, bool):
        no_income = income == 0
    else:
        unknown.append('individual_income_for_calendar_year is required')

    qc_this = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    qc_other = facts.get('individual_is_qualifying_child_of_any_other_taxpayer')
    not_qc = None
    if isinstance(qc_this, bool) and isinstance(qc_other, bool):
        not_qc = not qc_this and not qc_other
    else:
        unknown.append('qualifying-child status with respect to this taxpayer and every other taxpayer is required')

    conditions = (relationship_ok, no_income, not_qc)
    if False in conditions:
        return {'value': False, 'used_units': ['u152_d1_pred'], 'open_dependencies': []}
    if None in conditions:
        return {'value': None, 'used_units': ['u152_d1_pred'], 'open_dependencies': unknown}
    return {'value': True, 'used_units': ['u152_d1_pred'], 'open_dependencies': []}

def dependent_defined(facts):
    stated = facts.get('individual_is_dependent_of_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u152_a_dep_pred'], 'open_dependencies': []}

    stated_child = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    if stated_child is True:
        return {'value': True, 'used_units': ['u152_a_dep_pred', 'u152_c1_pred'], 'open_dependencies': []}

    used = ['u152_a_dep_pred']
    exclusion = married_dependent_exclusion_applies(facts)
    for unit in exclusion.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if exclusion.get('value') is True:
        return {'value': False, 'used_units': used, 'open_dependencies': []}

    child = qualifying_child(facts)
    for unit in child.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if child.get('value') is True:
        base = True
        base_open = []
    else:
        relative = qualifying_relative(facts)
        for unit in relative.get('used_units', []):
            if unit not in used:
                used.append(unit)
        if relative.get('value') is True:
            base = True
            base_open = []
        elif child.get('value') is False and relative.get('value') is False:
            base = False
            base_open = []
        else:
            base = None
            base_open = []
            for item in child.get('open_dependencies', []) + relative.get('open_dependencies', []):
                if item not in base_open:
                    base_open.append(item)

    if base is False:
        return {'value': False, 'used_units': used, 'open_dependencies': []}
    if base is True and exclusion.get('value') is False:
        return {'value': True, 'used_units': used, 'open_dependencies': []}
    open_dependencies = list(base_open)
    for item in exclusion.get('open_dependencies', []):
        if item not in open_dependencies:
            open_dependencies.append(item)
    return {'value': None, 'used_units': used, 'open_dependencies': open_dependencies}

def additional_exemption_for_dependent_applies(facts):
    stated = facts.get('individual_is_dependent_of_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u151_c_dependent_exemption_pred'], 'open_dependencies': []}
    result = dependent_defined(facts)
    used = ['u151_c_dependent_exemption_pred']
    for unit in result.get('used_units', []):
        if unit not in used:
            used.append(unit)
    return {'value': result.get('value'), 'used_units': used, 'open_dependencies': result.get('open_dependencies', [])}

def deduction_allowable_from_exemption_entitlement(facts):
    entitlement = facts.get('section151_exemption_entitlement_of_another_taxpayer_for_individual')
    if entitlement is True:
        return {'value': True, 'used_units': ['u151_a_allowance_pred'], 'open_dependencies': []}
    if entitlement is False:
        return {'value': None, 'used_units': ['u151_a_allowance_pred'], 'open_dependencies': ['a negative exemption-entitlement premise does not establish that no section 151 deduction was allowable']}
    return {'value': None, 'used_units': ['u151_a_allowance_pred'], 'open_dependencies': ['section151_exemption_entitlement_of_another_taxpayer_for_individual is required to derive an allowable deduction under section 151(a)']}

def dependent_disallowance_applies(facts):
    allowable = facts.get('section151_deduction_allowable_to_another_taxpayer_for_individual')
    if isinstance(allowable, bool):
        return {'value': allowable, 'used_units': ['u151_d2_disallow_pred'], 'open_dependencies': []}

    bridge = deduction_allowable_from_exemption_entitlement(facts)
    used = ['u151_d2_disallow_pred']
    for unit in bridge.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if bridge.get('value') is True:
        return {'value': True, 'used_units': used, 'open_dependencies': []}
    open_dependencies = ['section151_deduction_allowable_to_another_taxpayer_for_individual is required unless an affirmative exemption entitlement supplies it through section 151(a)']
    for item in bridge.get('open_dependencies', []):
        if item not in open_dependencies:
            open_dependencies.append(item)
    return {'value': None, 'used_units': used, 'open_dependencies': open_dependencies}

def special_year_exemption_rule_applies(facts):
    year = facts.get('query_year')
    if not isinstance(year, int) or isinstance(year, bool):
        return {'value': None, 'used_units': ['u151_d5_special_pred'], 'open_dependencies': ['query_year is required from the legal query']}
    return {'value': 2018 <= year <= 2025, 'used_units': ['u151_d5_special_pred'], 'open_dependencies': []}

def exemption_phaseout_applies(facts):
    used = ['u151_d3a_phaseout_pred']
    open_dependencies = []

    agi = facts.get('adjusted_gross_income')
    if not isinstance(agi, (int, float)) or isinstance(agi, bool):
        agi = None
        open_dependencies.append('adjusted_gross_income is required')

    amount = facts.get('applicable_amount_under_section_68_b')
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        amount_result = section68_applicable_amount(facts)
        amount = amount_result.get('value')
        for unit in amount_result.get('used_units', []):
            if unit not in used:
                used.append(unit)
        for item in amount_result.get('open_dependencies', []):
            if item not in open_dependencies:
                open_dependencies.append(item)

    if agi is None or amount is None:
        return {'value': None, 'used_units': used, 'open_dependencies': open_dependencies}
    return {'value': agi > amount, 'used_units': used, 'open_dependencies': []}

def applicable_percentage(facts):
    used = ['u151_d3b_pct_qty']
    applies = exemption_phaseout_applies(facts)
    for unit in applies.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if applies.get('value') is False:
        return {'value': 0, 'used_units': used, 'open_dependencies': []}
    if applies.get('value') is None:
        return {'value': None, 'used_units': used, 'open_dependencies': applies.get('open_dependencies', [])}

    agi = facts.get('adjusted_gross_income')
    amount = facts.get('applicable_amount_under_section_68_b')
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        amount_result = section68_applicable_amount(facts)
        amount = amount_result.get('value')
        for unit in amount_result.get('used_units', []):
            if unit not in used:
                used.append(unit)
        if amount is None:
            return {'value': None, 'used_units': used, 'open_dependencies': amount_result.get('open_dependencies', [])}

    separate_fact = facts.get('married_individual_filing_separate_return')
    if isinstance(separate_fact, bool):
        separate = separate_fact
    else:
        status = facts.get('filing_status')
        separate = None
        if isinstance(status, str):
            normalized = status.strip().lower().replace('-', '_').replace(' ', '_')
            if normalized in ('married_filing_separately', 'married_separate', 'mfs', 'separate_return'):
                separate = True
            elif normalized in ('joint', 'joint_return', 'married_filing_jointly', 'surviving_spouse', 'head_of_household', 'hoh', 'single', 'unmarried', 'not_married'):
                separate = False
        if separate is None:
            return {'value': None, 'used_units': used, 'open_dependencies': ['married-individual-filing-separate-return status is required to select the statutory increment']}

    step = 1250 if separate else 2500
    excess = agi - amount
    increments = int(excess // step)
    if excess % step != 0:
        increments += 1
    return {'value': min(100, 2 * increments), 'used_units': used, 'open_dependencies': []}
